else if trend = +1 and ((HC-close) / HC) > = (perOffHi / 100) then begin
trend = -1;
LC = close;
else if trend = -1 and ((close-LC) / LC) > = (perOffLo / 100) then begin
buy on close;
trend = +1;
HC = close;
( update LC & HC variables )
If close < LC then LC = close;
If close > HC then HC = close;
